function wastaBridge(){const selected=SALES_DATA.accounts.find(x=>x.id===activeRoute)||SALES_DATA.accounts[0];return `<section class="wasta-map"><div class="eyebrow">MIDDLE EAST / RELATIONSHIP ARCHITECTURE</div><h2>${st('两类入口，一条可交付的信任链。','Two routes. One deliverable chain of trust.')}</h2><p class="wasta-legend">${st('实线框为企业/生态直接入口，虚线框为可触达的战略关系路径；两类资源均可启动，所需时间、组织方式与投入不同。箭头表示项目推进路径。','Solid outlines show direct enterprise / ecosystem access; dashed outlines show reachable strategic relationship routes. Both can be activated, with different timelines, coordination and resources. Arrows show project progression.')}</p><div class="route-row"><span>${st('直接入口','DIRECT ACCESS')}</span><div>${SALES_DATA.accounts.filter(x=>x.access==='direct_confirmed').map(a=>`<button data-route="${a.id}" class="${a.id===activeRoute?'active':''}" aria-pressed="${a.id===activeRoute}">${accountName(a)}</button>`).join('')}</div></div><div class="route-row strategic"><span>${st('关系通路','RELATIONSHIP ROUTES')}</span><div>${SALES_DATA.accounts.filter(x=>x.kind==='strategic').map(a=>`<button data-route="${a.id}" class="${a.id===activeRoute?'active':''}" aria-pressed="${a.id===activeRoute}">${accountName(a)}</button>`).join('')}</div></div><div class="trust-chain">${[['信任引荐','Trusted introduction'],['业务赞助','Business sponsorship'],['共同工作组','Joint working group'],['采购与履约','Procurement and delivery']].map((x,i)=>`<div><b>0${i+1}</b><strong>${st(x[0],x[1])}</strong>${i<3?'<span>→</span>':''}</div>`).join('')}</div><div class="route-focus" aria-live="polite"><small>${selected.id} / ${selected.access==='direct_confirmed'?st('已确认直接入口','Confirmed direct access'):st('可触达战略关系','Reachable strategic relationship')}</small><h3>${accountName(selected)}</h3><p>${sv(selected.social_role)}</p><p><b>${st('先推进：','First move: ')}</b>${sv(selected.next)}</p></div></section>`;}
function wastaRules(){return `<section class="editorial-section">${sectionHeading('WASTA / SOCIAL CAPITAL INTO EXECUTION',st('把关系规则，转成可兑现的合作安排。','Turn relationship principles into executable cooperation.'),st('关系、互惠、层级与长期信任是理解背景；以下为执行建议，具体节奏以对方意愿、国别和企业流程为准。','Relationships, reciprocity, hierarchy and lasting trust provide context. The actions below are recommendations, subject to counterpart preference and local procedures.'))}<div class="wasta-principles">${[
['信任前置','Trust first','正式报价前明确引荐人、关系赞助人和可讨论议题；会前取得对材料接收和转发范围的同意。','Before a formal quote, identify the introducer, sponsor and agreed topic; obtain permission for receipt and onward sharing of materials.','交付：一页议题＋受邀角色＋披露范围','Output: one-page theme, invitees and disclosure scope'],
['互惠可兑现','Deliverable reciprocity','用业务诊断、技术演示、本地培训和持续服务贡献价值，承诺有负责人、有交付日期。','Contribute discovery, demonstrations, local training and continuing service; assign an owner and date to each commitment.','交付：双方贡献清单＋兑现记录','Output: contribution list and fulfillment record'],
['层级与工作层衔接','Connect sponsors to working teams','尊重既有介绍链；请赞助方指定运营、技术和采购角色。会后向引荐人反馈进度，避免绕开关系链单独施压。','Respect the introduction chain; ask the sponsor to nominate operations, technical and purchasing roles. Keep the introducer informed without pressuring the buyer.','交付：赞助人—业务拥有者—采购角色图','Output: sponsor, process-owner and procurement map'],
['长期信任分段兑现','Build trust through small outcomes','先完成小范围、可检验成果，再讨论更大投入；出现延期及时说明并协商重排。同步建立多角色关系，降低单点依赖。','Deliver a small testable outcome before expanding investment. Explain delays and agree revised plans; build multi-role relationships to reduce dependency.','交付：小成果＋复盘＋下一阶段共识','Output: small outcome, review and next-stage agreement']
].map((x,i)=>`<article><span>0${i+1}</span><h3>${st(x[0],x[1])}</h3><p>${st(x[2],x[3])}</p><small>${st(x[4],x[5])}</small></article>`).join('')}</div><p class="sales-small">${st('应用原则：关系用于促成受邀沟通、减少信息不对称并建立承诺；合同、采购权限、竞争程序和付款责任照常确认。顾问、培训、活动等费用只对应真实工作与交付，不作为关系费用的换名包装。','Use relationships to enable invited dialogue, reduce information gaps and build commitments. Confirm contracts, purchasing authority, procurement procedures and payment responsibilities. Advisory, training and event fees must reflect real work and outputs, not relabeled influence payments.')}</p><p class="source-inline">${st('背景依据：所供Wasta分析与组织研究；具体工作安排为方案建议。','Context: supplied Wasta analysis and organizational research; specific operating steps are proposed.')} <a href="https://www.cambridge.org/core/journals/management-and-organization-review/article/wasta-advancing-a-holistic-model-to-bridge-the-micromacro-divide/84B909B307A93B7703A654F2E649E064" target="_blank" rel="noopener">${st('研究参考 ↗','Research reference ↗')}</a></p></section>`;}
function salesOverview(){return intro('BUBIX / MIDDLE EAST RELATIONSHIPS',st('以信任打开对话，以履约沉淀关系。','Trust opens dialogue. Delivery sustains relationships.'),st('MAKE TRUST EASY. 聚焦海湾家族集团、地产运营、贸易生态与战略关系网络，把在地资源接到具体业务、采购和回款。','MAKE TRUST EASY. Connect Gulf family groups, property operations, trade ecosystems and strategic networks to defined business needs, procurement and collections.'))+`<div class="sales-cover"><div><div class="eyebrow">MIDDLE EAST ONLY / V3.4</div><h2>${st('四个直接入口，<br>四条战略关系通路。','Four direct routes.<br>Four strategic relationship paths.')}</h2><p>${st('Emaar、Al-Futtaim、Saif Belhasa、DMCC为已确认直接入口；沙特王室、主权投资商务圈层与泛阿拉伯资源同样可触达。以产品议题组织对话，以时间和成本推动项目。','Emaar, Al-Futtaim, Saif Belhasa and DMCC are confirmed direct routes. Saudi royal, sovereign-investment-circle and pan-Arab resources are also reachable. Organize dialogue around product propositions and invest time and resources to develop projects.')}</p><div class="proof-links">${sbutton('resources','02 打开关系与资源图谱','02 Relationship and resource map')}${sbutton('execution','03 查看关系牵引的对接计划','03 Trust-led execution plan')}</div></div><img src="assets/brand-gateway-v3.webp" width="1672" height="941" alt="${st('海湾信任之门品牌概念','Gulf gateway brand concept')}"></div><div class="sales-counts">${[['4','已确认直接入口','Confirmed direct routes'],['4','战略关系通路','Strategic relationship routes'],['2','拟定有价方案目标','Proposed priced-SOW goal'],['1','争取付费试点','Paid pilot pursued']].map(x=>`<div><b>${x[0]}</b><span>${st(x[1],x[2])}</span></div>`).join('')}</div>${salesNote()}${strategicFrame()}${wastaBridge()}<section class="editorial-section">${sectionHeading('RELATIONSHIP → BUSINESS → CASH',st('资源可达，产品切入，项目落地。','Reachable resources. Product-led entry. Executable projects.'))}<div class="sales-sequence">${[['02','resources','中东关系与资源','Middle East relationships','四核心入口＋四战略通路','Four core routes + four strategic paths'],['03','execution','信任与对接节奏','Trust-led execution','引荐、赞助、工作组与共创','Introduction, sponsorship and co-design'],['04','pipeline','商机与签约','Pipeline and contracts','合格需求、有价方案、正式合同','Qualified need, priced SOW and contract'],['05','delivery','交付与验收','Delivery and acceptance','可检验成果、交接与本地能力','Testable outcome, handover and capability'],['06','collections','回款与长期关系','Cash and sustained trust','付款责任、进度反馈与续期','Payments, progress feedback and renewal']].map(x=>`<button data-go="${x[1]}"><span>${x[0]}</span><strong>${st(x[2],x[3])}</strong><small>${st(x[4],x[5])}</small></button>`).join('')}</div></section>`;}
function salesResources(){const items=SALES_DATA.accounts.filter(x=>salesKind==='all'||x.kind===salesKind);return intro('02 / MIDDLE EAST RESOURCES & WASTA',st('把人脉网络，接到真正的业务主体。','Connect relationship networks to accountable businesses.'),st('四个直接入口与四条战略通路分别展示。关系角色、业务角色、采购权与付款责任保持独立；不按人脉头衔或覆盖国家数放大客户数量。','Show four direct routes and four strategic paths separately. Relationship roles, business ownership, purchasing authority and payment remain distinct; titles and country coverage do not multiply customers.'))+salesNote()+wastaBridge()+productLedPaths()+wastaRules()+`<div class="sales-filters" aria-label="${st('筛选资源角色','Filter resource roles')}">${[['all',st('全部8条路径','All 8 routes')],...Object.entries(kinds)].map(([k,v])=>`<button data-kind="${k}" class="${salesKind===k?'active':''}" aria-pressed="${salesKind===k}">${v}</button>`).join('')}</div><div class="account-grid">${items.map(a=>`<article class="account-card" id="account-${a.id}"><div class="account-meta"><span>${a.id} / ${a.priority}</span><span>${kinds[a.kind]}</span></div><h2>${esc(accountName(a))}</h2><div class="account-status">${a.access==='direct_confirmed'?st('直接入口可对接 / 2026.10.28；产品与预算按工作包推演','Direct access confirmed / 2026.10.28; infer product scope and budget from work packages'):st('战略关系可触达 / 2026.10.28；按议题组织、投入时间与商务资源','Strategic access confirmed / 2026.10.28; activate through a focused theme, time and commercial resources')} · ${a.window}</div><h3>${st('Wasta角色与入口','Wasta role and entry')}</h3><p>${sv(a.social_role)}</p><p>${sv(a.entry)}</p><h3>${st('可承接的业务议题','Proposed business theme')}</h3><p>${sv(a.offer)}</p><details><summary>${st('展开互惠价值、推进动作与条件','Reciprocal value, actions and conditions')}</summary><h3>${st('可兑现的合作价值','Deliverable reciprocal value')}</h3><p>${sv(a.reciprocity)}</p><h3>${st('下一步','Next step')}</h3><p>${sv(a.next)}</p><h3>${st('进入企业项目的条件','Enterprise-project gate')}</h3><p>${sv(a.gate)}</p><div class="account-stop">${sv(a.stop)}</div><p class="source-inline">${st('来源类别：','Source category: ')}${a.source.map(id=>{const x=SALES_DATA.sources.find(v=>v.id===id);return x?`<a href="${x.url}" target="_blank" rel="noopener">${id} ↗</a>`:id}).join(' · ')}</p></details></article>`).join('')}</div>`;}
const salesPhases=[
{d:'D1–15',title:['会前准备与信任牵引','Prepare and align the trust chain'],r:['四个直接入口完成议题与演示准备；选择两条可触达战略路径并行安排议题交流。','Prepare themes and demos for four direct routes; select two reachable strategic paths for parallel thematic dialogue.'],p:['完成四份客户议题卡、演示边界与本地价值说明；预算和总部接口就位。','Prepare four account briefs, demo boundaries and local-value propositions; secure resources and headquarters owners.'],c:['安排受邀工作会，不承诺采购结果；区分礼节交流、业务共识和实际授权。','Arrange invited working meetings without promising procurement; distinguish courtesy, business agreement and authority.'],out:['四份议题卡＋关系/决策角色图＋资源确认表','Four account briefs + relationship / decision-role map + resource checklist'],g:['对方接受议题、参会角色明确、资料权限与售前资源落实','Accepted theme, named participants, disclosure permission and presales capacity']},
{d:'D16–30',title:['关系会与业务诊断','Relationship dialogue and discovery'],r:['尊重既有联络链组织小范围沟通；会后向引荐人反馈已达成的下一步。','Arrange focused dialogue through the agreed contact chain; report agreed next steps to the introducer.'],p:['运营与技术共同确认真实问题、现有系统、数据权限及本地价值。','Operations and technology confirm the problem, current systems, data permissions and local value.'],c:['争取3–4次有效工作会，形成2份具名企业需求备忘录；DMCC生态会不计作买方需求。','Pursue 3–4 working meetings and two named-enterprise discovery memos; an ecosystem meeting is not buyer demand.'],out:['业务备忘录＋双方贡献清单＋会后48小时纪要','Discovery memos + mutual-contribution list + minutes within 48 hours'],g:['业务拥有者确认问题和下一步，且明确采购路径','Process owner confirms the problem, next step and procurement path']},
{d:'D31–45',title:['共同工作组与小成果','Joint team and small outcomes'],r:['请赞助方指定工作组；保持赞助人、业务负责人和交付接口三层联系。','Ask the sponsor to nominate a working team; maintain sponsor, process-owner and delivery connections.'],p:['用授权样本做有边界的演示，验证一个流程和一组验收方法。','Use authorized samples for a bounded demonstration of one workflow and acceptance method.'],c:['形成2份有价方案或诊断SOW，明确采购、付款与变更条件。','Develop two priced proposals or scoping SOWs with procurement, payment and change terms.'],out:['工作组名单＋可检验小成果＋有价方案','Named team + small testable outcome + priced proposal'],g:['范围、责任、预算路径和验收标准获得确认','Agreed scope, responsibility, budget path and acceptance criteria']},
{d:'D46–60',title:['合同与正式采购','Contract and formal procurement'],r:['按约定向引荐/赞助方反馈进度；由正式采购与业务团队推进条款。','Keep introducer / sponsor informed as agreed; procurement and business teams own formal terms.'],p:['锁定诊断/试点交付范围、数据责任、技术排期与本地培训。','Fix scoping / pilot boundaries, data responsibility, technical schedule and local training.'],c:['以生效合同和约定首款启动；礼节性支持和意向书不记收入。','Start against an effective contract and agreed payment; courtesy support or letters of intent are not revenue.'],out:['生效合同/首款进度＋交付启动或暂停决定','Contract / initial-payment status + start or hold decision'],g:['有权签署、资源与首款条件满足','Authorized signatures, scheduled resources and payment conditions']},
{d:'D61–75',title:['交付承诺与关系反馈','Deliver commitments and update the network'],r:['定期反馈交付进度，以真实小成果维护引荐人信用；问题及时沟通。','Use real progress to maintain introducer credibility; communicate problems promptly.'],p:['执行一个选定的付费验证，按真实启动日安排约6周。','Deliver one selected paid validation, allowing about six weeks from actual kickoff.'],c:['依据SOW记录验收、发票与付款；新增范围另行报价。','Record acceptance, invoices and payments under the SOW; quote changes separately.'],out:['测试与业务记录＋问题/变更台账','Test / business evidence + issue and change register'],g:['可复核交付与双方确认的下一里程碑','Reviewable delivery and an agreed next milestone']},
{d:'D76–90+',title:['验收、回款与长期合作','Acceptance, cash and sustained cooperation'],r:['向赞助方回报已兑现成果；经同意后再请求扩展引荐，不提前占用信任。','Report fulfilled commitments to the sponsor; seek further referrals only with consent and evidence.'],p:['按实际进度验收与培训；若D60启动6周试点，则可能D102验收。','Accept and train on the actual schedule; a D60 pilot kickoff may mean D102 acceptance.'],c:['复盘净合同、实际收入、到账和本地贡献；续期/JV另立商业条件。','Review net contracts, revenue, receipts and local contribution; renewals / JV terms require separate agreement.'],out:['回款证据＋关系承诺复盘＋续期/退出方案','Receipts + commitment review + renewal or exit plan'],g:['有交付与财务依据的继续合作决定','Continuation decision supported by delivery and financial evidence']}
];
function accountSchedule(){return `<section class="editorial-section">${sectionHeading('TWO TRACKS / DISTINCT GATES',st('直接入口推进项目，战略通路培育赞助。','Direct routes develop projects; strategic routes develop sponsorship.'))}<div class="tablewrap"><table><thead><tr><th>${st('路径','Route')}</th><th>D1–30</th><th>D31–60</th><th>D61–90+</th><th>${st('进入下一步','Next gate')}</th></tr></thead><tbody>${[
['Emaar / Al-Futtaim / Saif Belhasa','关系会＋业务诊断','工作组＋方案/采购','选定项目交付及回款','业务拥有者、预算路径与SOW','Relationship + discovery','Joint team + proposal / procurement','Selected-project delivery and cash','Process owner, budget path and SOW'],
['DMCC','生态议题与成员转介','具名成员需求与共同演示','成员自主采购/项目推进','每家成员独立建档，不重复计量','Ecosystem theme and member referral','Named-member discovery and demo','Independent member procurement','Separate member accounts; no duplicated volume'],
[st('两条王室支系通路','Two royal relationship routes'),'安排产业议题与引荐','受邀交流与企业转介','符合条件后企业工作组','具名运营企业及业务赞助','Arrange industry dialogue and introductions','Invited dialogue and referral','Enterprise team if qualified','Named enterprise and business sponsor'],
[st('主权基金商务圈层','Sovereign-investment business circle'),'准备产业价值议题并约见','产业价值说明与归口','正式机构/企业评审','独立采购主体与程序','Prepare industry themes and meetings','Industry-value brief and ownership','Formal entity / company assessment','Independent buyer and procedures'],
[st('泛阿拉伯顾问资源','Pan-Arab advisory route'),'组织专题与参会对象','小型行业交流与转介','企业项目单独跟进','企业问题、参会角色与下一步','Organize the theme and participants','Focused industry dialogue and referral','Separate enterprise follow-through','Problem, participants and next action']
].map(x=>`<tr><td>${x[0]}</td>${(salesEn?x.slice(5):x.slice(1,5)).map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="sales-small">${st('关系节点按路径管理，销售账户按实际采购法人及独立工作包管理；同一项目由多个关系引入只计一次。','Manage relationship nodes as routes, and sales accounts by actual purchasing entity and independent scope. Count one project once even if multiple relationships introduce it.')}</p></section>`;}
function salesExecution(){const p=salesPhases[salesPhase],tx=x=>st(x[0],x[1]);return intro('03 / WASTA-LED PROJECT EXECUTION',st('让信任进入工作组，让工作组推进履约。','Turn trust into a working team, and the team into delivery.'),st('关系线、业务线与商务线并行；D1以授权、预算和总部支持具备为起点。时间为规划窗口，实际节奏与对方共同约定。','Run relationship, business and commercial tracks together. D1 begins with authority, resources and headquarters support. Windows are planned and agreed with the counterpart.'))+`<section class="sales-roadmap"><div class="roadmap-tabs" role="tablist" aria-label="${st('选择对接阶段','Select execution stage')}">${salesPhases.map((x,i)=>`<button role="tab" data-phase="${i}" aria-selected="${i===salesPhase}" class="${i===salesPhase?'active':''}"><b>${x.d}</b><span>${tx(x.title)}</span></button>`).join('')}</div><div class="roadmap-deck"><div class="eyebrow">${p.d} / ${tx(p.title)}</div>${[['WASTA',p.r],['BUSINESS',p.p],['COMMERCIAL',p.c]].map(x=>`<div class="lane"><span>${x[0]}</span><p>${tx(x[1])}</p></div>`).join('')}<div class="roadmap-output"><strong>${st('交付物：','Output: ')}${tx(p.out)}</strong><p>${st('推进条件：','Next gate: ')}${tx(p.g)}</p></div></div></section>${accountSchedule()}${activationPlan()}${salesReadiness()}${wastaRoles()}`;}
function wastaRoles(){return `<section class="editorial-section">${sectionHeading('ONE MEETING / FIVE DISTINCT ROLES',st('每场会先确定五种角色。','Identify five distinct roles for each engagement.'))}<div class="delivery-weeks">${[
['引荐人','Introducer','负责进入对话与介绍范围；约定反馈方式。','Enables the introduction and agrees the feedback scope.'],['关系/业务赞助人','Sponsor','认可议题并指定对口团队；不默认拥有采购权。','Supports the theme and nominates a team; procurement authority is separate.'],['业务拥有者','Process owner','定义痛点、数据权限、流程和验收。','Owns the problem, data authority, workflow and acceptance.'],['采购/法务','Procurement / legal','确认程序、合同、供应商准入与责任。','Confirms procedures, contract, onboarding and responsibilities.'],['付款/财务','Finance / payer','确认付款法人、资金与回款节点。','Confirms paying entity, funding and payment milestones.']
].map((x,i)=>`<section><b>0${i+1}</b><h3>${st(x[0],x[1])}</h3><p>${st(x[2],x[3])}</p></section>`).join('')}</div></section>`;}
function strategicFrame(){return `<section class="editorial-section">${sectionHeading('STRATEGY / PRODUCTS × RELATIONSHIPS × EXECUTION',st('以产品定义机会，以资源打开市场。','Define the opportunity through products. Open markets through relationships.'),st('方案用于决定从哪里切入、投入什么、如何形成项目；按产品价值反推客户议题与预算区间，再通过商务推进逐步细化。','This plan selects entry points, resources and project paths. Product value informs account themes and indicative budgets, refined through commercial engagement.'))}<div class="campaign-flow">${[
['资源前提','Relationship foundation','四个企业/生态入口与四条战略关系路径均可触达，排期和投入决定推进速度。','All four enterprise / ecosystem routes and four strategic relationship routes are reachable; scheduling and investment determine pace.'],
['产品推演','Product-led planning','以场景、工作量、集成复杂度和持续服务反推需求、报价与收入组合；经营规模与总部成本采用规划参数，历史财务不作为已证实基准。','Infer demand, pricing and revenue mix from use cases, effort, integration complexity and ongoing service. Operating scale and HQ costs use planning assumptions; historical financials are not a verified baseline.'],
['执行落点','Execution focus','用一页议题、五分钟演示和有价工作包进入商务对话，推进工作组、合同、交付和回款。','Enter dialogue with a one-page theme, five-minute demo and priced scope; progress to a working team, contract, delivery and cash.']
].map(x=>`<section><h3>${st(x[0],x[1])}</h3><p>${st(x[2],x[3])}</p></section>`).join('')}</div></section>`;}
function productLedPaths(){return `<section class="editorial-section">${sectionHeading('PRODUCT → ACCOUNT → PROJECT',st('四个切口，两条增长主线。','Four entry points. Two growth engines.'),st('以下是产品与业务适配推演；预算按交付工作包反推，用于首轮商务讨论。','The following are proposed product / business fits. Budgets are derived from delivery scopes for initial commercial discussion.'))}<div class="tablewrap"><table><thead><tr><th>${st('入口','Route')}</th><th>${st('产品切口','Product wedge')}</th><th>${st('首轮交付','First deliverable')}</th><th>${st('后续规模化','Expansion path')}</th></tr></thead><tbody>${[
['Emaar','工程验收、供应商履约与资产运营记录','Project acceptance, supplier performance and asset-operation records','选定一个流程，演示多方状态与记录追溯','Demonstrate shared status and traceability for one workflow','项目模板→多项目接入→年度运维','Project template → multiple projects → annual support'],
['Al-Futtaim','汽车/供应商凭证与跨业务单元对账','Automotive / supplier credentials and cross-unit reconciliation','梳理一个业务单元的凭证与对账工作流','Map one business unit credential / reconciliation flow','单元试点→跨部门复制→持续服务','Unit pilot → cross-department reuse → recurring service'],
['Saif Belhasa','产业履约记录与本地技术服务协同','Industrial performance records and local technology-service cooperation','集团场景诊断或与本地技术团队共做演示','Group workflow discovery or a joint local-team demo','集团应用→联合交付→合作运营','Group application → joint delivery → cooperative operations'],
['DMCC','贸易凭证互操作与成员企业协作','Trade-credential interoperability and member collaboration','与既有Tradeflow等系统互补的场景演示','Demonstrate a complementary use case alongside systems such as Tradeflow','成员项目→贸易生态连接→按量服务','Member projects → ecosystem links → usage-based services']
].map(x=>`<tr><td>${x[0]}</td><td>${st(x[1],x[2])}</td><td>${st(x[3],x[4])}</td><td>${st(x[5],x[6])}</td></tr>`).join('')}</tbody></table></div><div class="two"><section class="card"><h3>${st('B线 / 企业场景：形成第一批可交付项目','Engine B / enterprise use cases: establish deliverable projects')}</h3><p>${st('从四个核心入口进入场景诊断与付费验证；诊断USD10,000–20,000、六周试点USD40,000–65,000为现有工作包规划区间。目标是形成可复制模板，再接实施、运维和增量服务。','Use the four core routes for discovery and paid validation. Existing scope assumptions are USD10,000–20,000 for discovery and USD40,000–65,000 for a six-week pilot. Build reusable templates, then implementation, support and incremental services.')}</p></section><section class="card"><h3>${st('A线 / 战略平台：培育更大合作空间','Engine A / strategic platforms: develop larger cooperation')}</h3><p>${st('王室、主权投资商务圈层及泛阿拉伯资源承担高层议题与产业组织牵引；以企业场景为演示载体，提出行业平台、节点网络和本地联合运营方案。组织多个参与方和平台采购，需另行配置时间、团队与资本。','Royal, sovereign-investment-circle and pan-Arab routes lead executive themes and industry organization. Use enterprise scenarios to demonstrate an industry platform, node network and local joint operations. Multi-party organization and platform procurement require their own time, team and capital.')}</p></section></div><p class="sales-small">${st('以可触达资源为基础，先形成有吸引力、可交付、能报价的产品方案；通过对接反馈逐步细化需求、预算和合作范围。','Start with reachable relationships and an attractive, deliverable, priceable product proposition. Refine needs, budgets and cooperation scope through engagement.')}</p></section>`;}
function activationPlan(){return `<section class="editorial-section">${sectionHeading('ACTIVATION / TIME AND RESOURCE COST',st('可触达的关系，要用时间和交付能力激活。','Activate reachable relationships with time and delivery capacity.'))}<div class="campaign-flow">${[
['D1–30 / 核心入口优先','D1–30 / prioritize core routes','四份议题卡和演示准备，围绕一个清晰业务问题安排工作会；关系预约、双语材料与本地出访进入商务预算。','Prepare four account briefs and demos. Arrange working sessions around one defined business problem; budget coordination, bilingual materials and local visits.'],
['D15–60 / 战略议题并行','D15–60 / develop strategic themes','从四条可触达战略路径中优先推进最多两条，围绕产业平台价值、共同利益与本地能力组织交流；其余路径按机会顺延。','Activate at most two of the four reachable strategic routes initially, around industry-platform value, mutual interests and local capability; sequence the others as opportunities develop.'],
['D31–90+ / 项目优先交付','D31–90+ / prioritize project delivery','售前与商务力量集中到最有推进势能的两个方案，争取一个付费试点；大平台合作沿独立中长期节奏推进。','Concentrate commercial and presales resources on the two propositions with strongest momentum, pursuing one paid pilot; larger platform partnerships follow a separate longer-term cadence.']
].map(x=>`<section><h3>${st(x[0],x[1])}</h3><p>${st(x[2],x[3])}</p></section>`).join('')}</div><p class="sales-small">${st('USD85,000–135,000仍为90日商务/售前资源配置建议，保障四个核心入口及选择性的战略关系激活；不是八条路径同时全面铺开，也不含大型平台建设和试点交付。成本对应人员、差旅、材料、演示、专业服务及持续协调。','The USD85,000–135,000 90-day resource envelope supports four core routes and selective strategic activation. It does not fund full concurrent deployment across all eight routes, major platform construction or pilot delivery. Costs cover people, travel, materials, demos, professional services and ongoing coordination.')}</p></section>`;}
function annualRevenuePath(){return `<section class="editorial-section">${sectionHeading('YEAR ONE / A PRODUCT-LED REVENUE PATH',st('年度收入，是产品组合与交付节奏的结果。','Annual revenue follows product mix and delivery cadence.'))}<div class="campaign-flow">${[
['M1–3 / 建立首批项目','M1–3 / establish first projects','以四个核心入口组织需求诊断与付费试点，沉淀演示、SOW和报价模板。','Use the four core routes for discovery and paid pilots, building reusable demos, SOWs and pricing templates.'],
['M4–6 / 从试点到生产','M4–6 / move from pilot to production','围绕首个场景扩展系统接口、参与方及应用范围，形成生产实施和持续服务合同。','Expand interfaces, participants and scope around the initial use case, leading to production implementation and recurring services.'],
['M7–12 / 复制与运营','M7–12 / replicate and operate','将模板复制到同集团其他项目及生态伙伴，以运维、订阅和净新增用量扩大持续收入。','Reuse templates across group projects and ecosystem partners, expanding recurring revenue through support, subscriptions and incremental usage.']
].map(x=>`<section><h3>${st(x[0],x[1])}</h3><p>${st(x[2],x[3])}</p></section>`).join('')}</div><p class="sales-small">${st('推演公式：年度收入＝当年履约的诊断/实施/试点收入＋履约月份×订阅与运维月费＋净新增计费量×单价。由产品工作量、售价与交付容量推导；客户对接后滚动替换参数，签约额和回款另行管理。','Planning formula: annual revenue = discovery / implementation / pilot work delivered in-year + service months × subscription / support fee + net incremental billable units × price. Derive it from product effort, pricing and delivery capacity, refining inputs through engagement; manage contract value and cash separately.')}</p></section>`;}
const salesGates=[['S0','目标资源','Target route','可触达资源与产品议题匹配，形成首轮对接方案','Match reachable resources to product themes and prepare the initial proposition'],['S1','有效接洽','Verified contact','近期沟通与具体业务负责人；不只是名片','Recent communication with a relevant process owner, not a business card'],['S2','需求合格','Qualified need','问题、买方、数据、预算路径、时间明确','Confirmed problem, buyer, data, budget path and timing'],['S3','有价方案','Priced SOW','明确范围、报价、验收、采购及付款条件','Defined scope, price, acceptance, procurement and payments'],['S4','有效签约','Effective contract','双方有权签署且合同生效；记录净合同额','Authorized signatures and effective contract; record net value'],['S5','交付验收','Accepted delivery','取得合同约定的验收证据；财务确认收入','Contractual acceptance evidence; finance determines revenue'],['S6','实际回款','Cash received','银行到账与合同/发票勾稽；不是口头付款承诺','Bank receipt reconciled to contract / invoice, not a payment promise']];
function salesPipeline(){return intro('04 / PIPELINE TO CONTRACT',st('从产品价值，推导项目与年度收入。','Build project and annual revenue plans from product value.'),st('四个核心入口以产品适配推演形成首轮方案；战略关系承担高层牵引与平台合作。以下工作量和预算用于战略配置与商务讨论。','Product-fit planning defines initial propositions for the four core routes; strategic relationships support executive dialogue and platform cooperation. The following effort and budgets guide strategic allocation and commercial discussion.'))+annualRevenuePath()+`<div class="stage-register">${salesGates.map(x=>`<section><span>${x[0]}</span><h3>${st(x[1],x[2])}</h3><p>${st(x[3],x[4])}</p></section>`).join('')}</div><section class="editorial-section">${sectionHeading('90-DAY WORKLOAD PLAN',st('90日目标：四场工作会、两项需求、两份方案、一个付费试点。','90-day goals: four working meetings, two needs, two proposals and one paid pilot.'))}<div class="sales-counts">${[['4','核心入口工作会','Core-route working meetings'],['2','合格企业需求目标','Qualified enterprise needs'],['2','有价SOW目标','Priced-SOW goal'],['1','争取付费试点','Paid pilot pursued']].map(x=>`<div><b>${x[0]}</b><span>${st(x[1],x[2])}</span></div>`).join('')}</div><p class="muted">${st('规划约束：一名区域负责人每周安排1–2次有准备的商务工作会；总部指定一名售前接口并锁定交付窗口。未形成业务赞助、合格需求、预算路径或售前支持时，调整节奏与投入。','Capacity assumption: one regional lead schedules 1–2 prepared working meetings a week, with a designated headquarters presales owner and delivery window. Adjust pacing and investment if sponsorship, qualified demand, budget paths or presales support do not materialize.')}</p></section><section class="pricing-panel"><div class="eyebrow">BOTTOM-UP / USD</div><h2>${st('从小范围付费工作包开始。','Start with bounded, paid work packages.')}</h2><div class="two"><div><h3>${st('付费诊断：USD 10,000–20,000 / 项','Paid scoping: USD 10,000–20,000 each')}</h3><p>${st('2–3人周 × USD 2,500，加外部服务USD 1,000–2,000；成本加15%缓冲，再按35%目标毛利反推，约USD 10,600–16,800，形成商务讨论区间；USD10,000报价在最低缓冲成本下毛利约31%，每份报价须另作成本及35%目标毛利校核。','2–3 person-weeks x USD 2,500 plus USD 1,000–2,000 external services; add 15% contingency and divide by (1 - 35% target gross margin): about USD 10,600–16,800, used as a commercial discussion band. At minimum buffered cost, a USD 10,000 quote yields about 31% gross margin; check each quote against costs and the 35% target.')}</p></div><div><h3>${st('6周付费试点：USD 40,000–65,000 / 项','Six-week paid pilot: USD 40,000–65,000 each')}</h3><p>${st('6–10人周 × USD 3,000，加云/安全测试USD 3,000–6,000；同样15%缓冲和35%目标毛利，约USD 37,200–63,700。单价、工时均为估算，须总部核价。','6–10 person-weeks x USD 3,000 plus USD 3,000–6,000 cloud / security testing; the same contingency and margin give about USD 37,200–63,700. Rates and effort are estimates requiring headquarters quotation.')}</p></div></div><p class="sales-small">${st('35%为工作包报价的拟定毛利目标，不含区域固定费、总部费用、税费与融资；渠道费用另入成本。它不等于v3.2的平台贡献率，也不是既往实际毛利。','The 35% is a proposed work-package gross-margin target before regional / headquarters fixed costs, tax and financing; add channel fees to costs separately. It is neither the v3.2 operator contribution margin nor historical performance.')}</p><div class="quote-toggle"><label><input id="scopingCredit" type="checkbox">${st('其中一项诊断费全额抵扣其后试点','Credit one scoping fee in full against the subsequent pilot')}</label></div><div id="salesScenario" aria-live="polite"></div><p class="sales-small">${st('两项诊断与一项试点必须有独立付费权益。默认区间为2×诊断＋1×试点；若抵扣一项诊断，净合同情景变为USD 50,000–85,000。不可重复计算，也不将该情景挂到尚未确认的具名客户上。','Scoping and pilot must carry distinct paid entitlements. Default: two scoping engagements plus one pilot. Crediting one scoping fee gives USD 50,000–85,000 net contracts. Avoid duplication; do not assign these values to unqualified named accounts.')}</p></section><div class="notice">${st('既有USD 480万签约、363.75万营收是v3.2供货组合底稿，不是当前具名客户预测。年度目标按产品单价、项目组合、上线节奏和持续服务推演，再用商务反馈滚动调整；国家平台合作另按中长期路径推进。','The v3.2 USD 4.8m contracts / USD 3.6375m revenue mix is supporting scenario work, not this named-account forecast. Build annual targets from product pricing, project mix, rollout cadence and recurring services, then refine them with commercial feedback. National-platform cooperation follows a separate longer-term path.')}</div>`;}
function salesDelivery(){return intro('05 / SCOPE TO ACCEPTANCE',st('把“想合作”变成可验收的工作包。','Turn interest into a clearly defined work package.'),st('以下为建议的最小交付边界，最终以双方签署SOW为准；六周从实际启动日起算。','Proposed minimum scope, subject to a signed SOW. The six-week clock starts on the actual kickoff date.'))+`<div class="two"><section class="card"><h2>${st('诊断包 · 约2周','Scoping package / about 2 weeks')}</h2><p>${st('需求基线、现有/目标流程、系统接口、数据权限、技术边界、成本与试点SOW。交付以评审会和书面确认结束。','Deliver a baseline, current / target workflow, interfaces, data rights, technical boundaries, costs and pilot SOW. Close with a review meeting and written acceptance.')}</p></section><section class="card"><h2>${st('试点包 · 约6周','Pilot package / about 6 weeks')}</h2><p>${st('一期只覆盖一种凭证、两类参与方、最多3个约定接口及一个工作流；测试环境优先，不默认硬件、生产迁移或代币发行。','One credential type, two participant roles, up to three agreed interfaces and one workflow. Start in a test environment; hardware, production migration and token issuance are excluded by default.')}</p></section></div><div class="delivery-weeks">${[['W1','基线与权限','Baseline and permissions','签署范围、数据授权、验收用例','Agree scope, data rights and test cases'],['W2–3','集成与构建','Integrate and build','接口、凭证与权限工作流','Interfaces, credentials and permission workflow'],['W4','联合测试','Joint testing','正常、异常、撤销、越权与留痕','Positive, exception, revocation, access and trace tests'],['W5','业务验收','Business acceptance','买方依据SOW复核证据与缺陷','Buyer reviews evidence and defects under the SOW'],['W6','交接与收款','Handover and collection','培训、交接、验收单与付款文件','Training, handover, acceptance and payment documents']].map(x=>`<section><b>${x[0]}</b><h3>${st(x[1],x[2])}</h3><p>${st(x[3],x[4])}</p></section>`).join('')}</div><section class="editorial-section">${sectionHeading('ACCEPTANCE WITH EVIDENCE',st('三项验收，三个责任方。','Three acceptance tests. Clear ownership.'))}<div class="campaign-flow"><section><h3>${st('业务有效','Business validity')}</h3><p>${st('买方流程负责人确认：记录确实对应业务；建议至少30条授权样本、5类异常情形，数量须双方约定。','The buyer process owner confirms business relevance. Propose at least 30 authorized samples and five exception classes; agree quantities in the SOW.')}</p></section><section><h3>${st('技术可复核','Technical verification')}</h3><p>${st('总部交付负责人提交测试日志、权限结果、凭证签发/撤销及故障处理记录；性能指标先测基线再定阈值。','Headquarters delivery provides test logs, access results, issuance / revocation and incident records. Measure a baseline before setting performance thresholds.')}</p></section><section><h3>${st('商业可结算','Commercial settlement')}</h3><p>${st('合同经理与财务核对验收签署人权限、交付清单、开票条件和回款节点；缺陷与变更单独登记。','Commercial and finance teams verify acceptance authority, deliverables, invoice conditions and payment milestones. Track defects and changes separately.')}</p></section></div></section><div class="notice">${st('SOW外新增接口、额外参与方、生产迁移、额外安全要求，须变更报价及验收日期。不能以“技术试用”掩盖无限免费售前。','Additional interfaces, participants, production migration or security requirements need a change order and revised timing. A technical trial must not become unlimited unpaid presales.')}</div>`;}
function salesCollections(){return intro('06 / CONTRACT TO CASH',st('签约、收入、到账，分别交账。','Account separately for contracts, revenue and cash.'),st('首要结果指标是可勾稽的实际回款；签约与验收是驱动指标，不能互相替代。','The primary outcome is reconciled cash receipts. Contracts and acceptance are drivers, not substitutes.'))+`<div class="two"><section class="card"><h2>${st('诊断：建议60% / 40%','Scoping: proposed 60% / 40%')}</h2><p>${st('合同生效首款60%；书面验收后40%。两项独立诊断USD 20,000–40,000，对应拟定首款USD 12,000–24,000。','60% on effective contract, 40% after written acceptance. Two independent scopes totaling USD 20,000–40,000 imply proposed initial payments of USD 12,000–24,000.')}</p></section><section class="card"><h2>${st('试点：建议40% / 50% / 10%','Pilot: proposed 40% / 50% / 10%')}</h2><p>${st('生效首款40%；验收50%；约定30日稳定期后10%。一项USD 40,000–65,000试点，对应拟定首款USD 16,000–26,000。','40% on effective contract, 50% on acceptance, 10% after an agreed 30-day stabilization period. A USD 40,000–65,000 pilot implies USD 16,000–26,000 initial payment.')}</p></section></div><div class="sales-cash-band"><h2>${st('USD 28,000–50,000','USD 28,000–50,000')}</h2><p>${st('仅在2项诊断＋1项试点均独立签署、无抵扣且首款足额到账的条件下成立；是拟定首款情景，不是90日总回款或到账预测。','Conditional initial-payment scenario only: two independent scopes and one pilot, no credits, all initial payments received. Not total 90-day receipts or a cash forecast.')}</p></div><div class="tablewrap"><table><thead><tr><th>${st('指标','Metric')}</th><th>${st('定义与证据','Definition and evidence')}</th><th>${st('复盘节奏 / 责任','Cadence / owner')}</th></tr></thead><tbody>${[['实际回款','Cash receipts','银行到账按合同及发票匹配；金额与币种分列；缺少凭证为待核实，不填0冒充实绩。','Bank receipts matched to contracts / invoices, by currency. Missing evidence is unknown, not zero.','周 / 财务确认，区域推进','Weekly / finance verifies, regional lead follows through'],['有效净合同额','Effective net contracts','仅统计生效合同；扣除抵扣、取消、重复权益和转售重复计量。','Effective contracts only; deduct credits, cancellations and duplicated entitlements / resale counts.','周 / 商务＋财务','Weekly / commercial + finance'],['验收与收入','Acceptance and revenue','验收证据、服务期及权利义务支持确认；财务按实际合同判断，不以收款代替收入。','Acceptance, service periods and obligations support recognition; finance determines treatment, not cash alone.','月 / 交付＋财务','Monthly / delivery + finance'],['护栏：投入与应收','Guardrail: effort and receivables','无授权/无付费SOW时，只做受控需求发现；逾期应收与超范围工时触发升级，不默认继续投入。','Limit work to controlled discovery before authorization / paid SOW. Escalate overdue receivables and out-of-scope effort.','周 / 区域＋交付','Weekly / regional + delivery']].map(x=>`<tr><td>${st(x[0],x[1])}</td><td>${st(x[2],x[3])}</td><td>${st(x[4],x[5])}</td></tr>`).join('')}</tbody></table></div><section class="proof-door"><h2>${st('区域贡献可记录，股权回报另行核算。','Track regional contribution; account for equity separately.')}</h2><p>${st('获客、引荐、签约、回款、毛利和持续运营贡献按实际职责归属；渠道收益、供应商收入与JV收入不相加。激励触发及费率另行约定，不预设。','Attribute acquisition, referral, contracting, collection, margin and recurring operations to actual responsibilities. Do not add channel, supplier and JV revenue together. Agree incentive triggers and rates separately.')}</p></section>`;}
function bindSales(){document.querySelectorAll('[data-route]').forEach(x=>x.onclick=()=>{activeRoute=x.dataset.route;render()});document.querySelectorAll('[data-account-ref]').forEach(x=>x.onclick=()=>{salesKind='all';go('resources');requestAnimationFrame(()=>document.getElementById('account-'+x.dataset.accountRef)?.scrollIntoView({block:'start'}))});document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>go(x.dataset.go));document.querySelectorAll('[data-kind]').forEach(x=>x.onclick=()=>{salesKind=x.dataset.kind;render()});document.querySelectorAll('[data-phase]').forEach(x=>x.onclick=()=>{salesPhase=+x.dataset.phase;render()});const credit=document.querySelector('#scopingCredit');if(credit){const update=()=>{document.querySelector('#salesScenario').innerHTML=`<div class="sales-counts"><div><b>${credit.checked?'50,000–85,000':'60,000–105,000'}</b><span>${st('USD / 拟定净合同情景','USD / proposed net-contract scenario')}</span></div><div><b>${credit.checked?st('重排','Recalculate'):'28,000–50,000'}</b><span>${credit.checked?st('抵扣后按净合同重排首款','Rebuild initial payments after credits'):st('USD / 独立合同首款情景','USD / initial-payment scenario')}</span></div></div>`};credit.onchange=update;update();}}
const budgetRows=[
['区域商务资源','Regional commercial capacity','3个月 × 10,000–15,000','3 months x 10,000–15,000',30000,45000],
['总部售前架构','Headquarters presales','1.5人月 × 10,000–14,000','1.5 person-months x 10,000–14,000',15000,21000],
['演示与方案构建','Demo / solution preparation','1人月 × 8,000–12,000','1 person-month x 8,000–12,000',8000,12000],
['本地商务与法律服务','Local commercial / legal services','20–30小时 × 250–350','20–30 hours x 250–350',5000,10500],
['总部/跨境对接出访','HQ / cross-border visits','2批 × 3,000–5,000','2 visits x 3,000–5,000',6000,10000],
['小型业务会与翻译','Focused meetings / interpreting','4场 × 500–1,000','4 meetings x 500–1,000',2000,4000],
['云与安全演示环境','Cloud / security demo environment','3个月 × 1,000–2,000','3 months x 1,000–2,000',3000,6000],
['四份双语账户方案','Four bilingual account briefs','4套 × 600–1,200','4 sets x 600–1,200',2400,4800]
];
function salesReadiness(){return `<section class="editorial-section" id="readiness">${sectionHeading('RESOURCES THAT CAN DELIVER',st('预算保障的是兑现能力与持续在场。','Fund the ability to deliver and remain present.'),st('四个直接入口分别准备，战略通路以确认后的议题推进；通过真实交付维护关系信用。','Prepare each direct route separately, and progress strategic paths through agreed themes; sustain credibility through real delivery.'))}<div class="sales-cash-band"><h2>USD 85,000–135,000</h2><p>${st('建议90日商务与售前资源配置区间，含人员分摊和15%预留。非已批准预算，也不等于新增现金；逐项替换为实际资源与报价后审批。','Proposed 90-day commercial / presales resource envelope, including personnel allocation and 15% contingency. Not approved funding or incremental cash; replace assumptions with actual resources and quotes.')}</p></div><details class="operating-layer"><summary>${st('展开四个账户的资源准备预算 / USD','Expand the four-account readiness budget / USD')}</summary><div class="tablewrap"><table><thead><tr><th>${st('资源','Resource')}</th><th>${st('工作量假设','Workload assumption')}</th><th>USD</th></tr></thead><tbody>${budgetRows.map(x=>`<tr><td>${st(x[0],x[1])}</td><td>${st(x[2],x[3])}</td><td>${fmt(x[4])}–${fmt(x[5])}</td></tr>`).join('')}</tbody></table></div><p class="sales-small">${st('基础合计USD71,400–113,300；加15%预留为USD82,110–130,295，向上取整至85,000–135,000。单价为配置假设，非市场报价或个人薪酬主张。','Base USD71,400–113,300; with 15% contingency USD82,110–130,295, rounded upward to USD85,000–135,000. Rates are resource assumptions, not market quotes or individual compensation demands.')}</p><p class="sales-small">${st('与年度人员、差旅和有价工作包逐项去重；不含硬件、JV/许可资本或付费试点交付成本。会议/专业服务对应真实工作，不支付影响力购买费用。资源包不能由首轮合同额直接证明盈亏平衡。','Deduplicate annual staffing, travel and paid work packages. Excludes hardware, JV / licensing capital and paid-pilot delivery. Meeting / professional costs must reflect real work, not purchased influence. First-round contracts do not establish break-even.')}</p></details><div class="campaign-flow"><section><h3>${st('四份会前方案','Four meeting briefs')}</h3><p>${st('每家一页关系与议题卡、两页执行说明：对口角色、本地价值、流程、演示、边界、验收和下一步。','For each account: one relationship / theme page and two execution pages covering roles, local value, workflow, demo, limits, acceptance and next action.')}</p></section><section><h3>${st('承诺与责任到人','Owned commitments')}</h3><p>${st('明确资源牵引、总部售前、架构交付与财务法务接口；每项承诺登记负责人、完成日和反馈范围。','Assign relationship, presales, delivery, finance and legal owners. Record owner, due date and feedback scope for each commitment.')}</p></section><section><h3>${st('按共识释放资源','Release against agreement')}</h3><p>${st('预算可用后启动会前准备；业务赞助与需求备忘录形成后追加售前；合同及首款条件满足后投入交付。关系维护与采购审批分别管理。','Begin preparation with available funds, add presales after sponsorship and a discovery memo, and release delivery against contract and payment conditions. Relationship stewardship and purchasing approval remain distinct.')}</p></section></div></section>`;}
const legacySalesRender=render;
render=function(){const view=location.hash.slice(1)||'overview',query=document.querySelector('#search').value.trim();const custom={overview:salesOverview,resources:salesResources,execution:salesExecution,pipeline:salesPipeline,delivery:salesDelivery,collections:salesCollections};if(custom[view]&&!query){motionCleanup();document.querySelector('#app').innerHTML=custom[view]();bindVisual();}else legacySalesRender();if(query){const matches=SALES_DATA.accounts.filter(a=>JSON.stringify(a).toLowerCase().includes(query.toLowerCase()));if(matches.length)document.querySelector('#app').insertAdjacentHTML('afterbegin',`<section class="card"><h2>${st('目标客户检索','Target-account search')}</h2>${matches.map(a=>`<button class="search-result" data-account-ref="${a.id}">${esc(accountName(a))}<p>${sv(a.offer)}</p></button>`).join('')}</section>`);}document.querySelector('#nav').innerHTML=salesNav.map(([id,t],i)=>`<button data-go="${id}" class="${view===id?'active':''}" aria-current="${view===id?'page':'false'}"><b>${String(i+1).padStart(2,'0')}</b>${t}</button>`).join('');if(!query&&['manual','v3model','calculator','history'].includes(view))document.querySelector('#app').insertAdjacentHTML('afterbegin',`<div class="sales-boundary">${st('v3.2经营底稿作为历史假设附件保留；最新资源、接洽和销售目标以02–06项为准。','The v3.2 report is retained as a supporting historical scenario. Sections 02–06 govern the current account and sales plan.')}</div>`);if(!query&&view==='sources')document.querySelector('#app').insertAdjacentHTML('afterbegin',`<section class="card"><h2>${st('v3.4中东资源与Wasta依据','v3.4 Middle East resources and Wasta evidence')}</h2><p>${st('关系通路材料、直接入口确认、Wasta背景研究、公开职务与规划建议分别记录；公共职务不证明私人关系或采购授权。','Separate relationship materials, direct-access confirmation, Wasta research, public offices and recommendations. Public office does not prove a private relationship or procurement authority.')}</p><a class="btn" href="files/sales-targets-v3.4.json">${st('目标客户与来源登记JSON','Accounts and source register JSON')}</a><a class="btn" href="files/sales-action-plan-v3.4-${salesEn?'en':'zh'}.txt">${st('销售行动提要','Sales action brief')}</a></section>`);bindSales();};
window.removeEventListener('hashchange',legacySalesRender);window.addEventListener('hashchange',render);document.querySelector('#search').oninput=render;render();
